DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category_id` bigint NOT NULL,
  `brand_id` bigint DEFAULT '0',
  `name` varchar(150) NOT NULL COMMENT '商品名=品牌+型号',
  `model` varchar(150) NOT NULL COMMENT '型号',
  `img_dir` varchar(500) NOT NULL COMMENT '图片相对目录(billiard_img下)',
  `main_img` varchar(50) NOT NULL DEFAULT 'pic1.jpg' COMMENT '主图文件名',
  `pic_count` int NOT NULL DEFAULT '1' COMMENT '图片数量(用于生成详情轮播图pic1~picN)',
  `cue_type` varchar(20) DEFAULT NULL COMMENT '大头杆/小头杆',
  `hardness` varchar(20) DEFAULT NULL COMMENT '硬度等级',
  `tip_diameter` decimal(5,1) DEFAULT NULL COMMENT '先角/皮头直径mm',
  `weight` decimal(5,1) DEFAULT NULL COMMENT '杆重oz',
  `material` varchar(100) DEFAULT NULL,
  `spec` varchar(100) DEFAULT NULL,
  `applicable_scene` varchar(100) DEFAULT NULL,
  `params` text COMMENT '结构化参数JSON',
  `description` text,
  `stock` int NOT NULL DEFAULT '0',
  `sales` int DEFAULT '0',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1上架0下架',
  `sort` int DEFAULT '0',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `fit_play` varchar(20) DEFAULT NULL COMMENT '适配打法:准度防守/追分走位/均衡打法',
  `fit_power` varchar(20) DEFAULT NULL COMMENT '适配发力:轻推发力/均匀发力/大力发力',
  PRIMARY KEY (`id`),
  KEY `idx_prod_cat` (`category_id`),
  KEY `idx_prod_brand` (`brand_id`),
  KEY `idx_prod_status` (`status`),
  KEY `idx_prod_cue` (`cue_type`)
) ENGINE=InnoDB AUTO_INCREMENT=238 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `product`
--

LOCK TABLES `product` WRITE;
/*!40000 ALTER TABLE `product` DISABLE KEYS */;
